    }
    META_MODEL["__Field"] = {
        m.name: m
        for m in (
            _meta("name", _non_null(STRING), _field_name),
            _meta("description", STRING, _field_description),
            _meta(
                "args",
                _non_null(_list(_non_null(_nt("__InputValue")))),
                _field_args,
