    META_MODEL["__InputValue"] = {m.name: m for m in input_value_fields}
    META_MODEL["__EnumValue"] = {
        m.name: m
        for m in (
            _meta("name", _non_null(STRING), _enum_value_name),
            _meta("description", STRING, _enum_value_description),
